// Generated by scripts/sync-help.mjs from pzza-code-web/components/docs/terminal/PromptsShot.tsx. Regenerate with `npm run sync:help` rather than editing.
/**
 * Saved prompts: the broadcast bar's Saved prompts menu open over three
 * selected sessions, ported from the app's BroadcastBar and its PromptPicker
 * (src/grid/BroadcastBar.tsx) with the prompts PzzaCode starts with
 * (DEFAULT_PROMPTS in src/state/prompts.ts). Picking one fills the message
 * for review, as in the app; Send (or Enter) delivers it and the bar reports
 * where it went. The dock is placed and the grid leaves room for it the way
 * the app measures them.
 */
import { useEffect, useId, useLayoutEffect, useRef, useState, type CSSProperties, type KeyboardEvent } from "react";
import { Bot, MessageSquareText, Mic, Radio, SendHorizontal, X } from "lucide-react";
import { AgentMark, Term, Tile } from "../../home/AppUI";
import { AnsiScreen } from "../../home/ansi";
import { Shot, THIS_MAC } from "../../home/Chrome";
import { ActiveCanvas } from "../../home/Interactive";
import { AppWindow, SESSIONS, type Box, type SessionId } from "../../home/Scenes";
import { Viewport } from "./parts";
import { WIDE } from "./frames";

const PROMPTS = [
  { id: "default-tests", name: "Write tests", text: "Write tests for the current changes. Cover the edge cases, run them and fix anything that fails." },
  { id: "default-review", name: "Review this diff", text: "Review this diff for bugs, edge cases and security issues. List the findings by severity with file and line." },
  { id: "default-pr", name: "Write the PR description", text: "Write the PR description for the current changes: what changed, why, and how it was tested." },
  { id: "default-explain", name: "Explain this code", text: "Explain what the code in this folder does and how the main pieces fit together." },
  { id: "default-commit", name: "Write a commit message", text: "Write a concise commit message for the staged changes, with a short body listing the main changes." },
];

// The canvas padding (--space) and the composer's lift off the bottom (--broadcast-lift).
const SPACE = 10;
const LIFT = 24;
// Framed on the composer at the bottom of an 820 x 900 window with its four
// sessions in one column: the composer (760px wide, centred) needs the card
// to show the window's full width, so both sides of the card fall outside
// the window, and one column keeps each tile wide enough for the 86 column
// captures. The two upper rows are fixed in pixels so the gap between them
// (y 227..237) stays put when the composer grows and the lower rows shrink;
// the card starts in it, with the window's top bar and the first tile above.
const WINDOW = { width: 820, height: 900 };
const TOP_ROW = 175;
const CARD_TOP = 52 + TOP_ROW + SPACE / 2;
// The wallpaper beside and under the window.
const MARGIN = { side: 20, bottom: 24 };
const FRAME = { width: WINDOW.width + 2 * MARGIN.side, height: WINDOW.height + MARGIN.bottom - CARD_TOP };
const BOX: Box = { left: MARGIN.side, top: -CARD_TOP, ...WINDOW };
const DOCK = { left: 0, width: WINDOW.width, bottom: 0, "--broadcast-lift": `${LIFT}px` } as CSSProperties;
const ORDER: SessionId[] = ["api", "web", "docs", "release"];
const SELECTED: SessionId[] = ["api", "web", "docs"];
// The input grows with its text up to this many lines, then scrolls.
const MAX_INPUT_LINES = 6;

/** The app's PromptPicker, opened. */
function PromptPicker({ onPick }: { onPick: (text: string) => void }) {
  const [open, setOpen] = useState(true);
  const root = useRef<HTMLDivElement>(null);
  const trigger = useRef<HTMLButtonElement>(null);
  useEffect(() => {
    if (!open) return;
    // A press elsewhere in the scene closes it; the rest of the page is not the app.
    const away = (event: MouseEvent) => {
      if (!(event.target instanceof Node)) return;
      const scene = root.current?.closest(".pz");
      if (scene?.contains(event.target) && !root.current?.contains(event.target)) setOpen(false);
    };
    document.addEventListener("mousedown", away);
    return () => document.removeEventListener("mousedown", away);
  }, [open]);
  const onMenuKey = (event: KeyboardEvent<HTMLDivElement>) => {
    const items = [...(root.current?.querySelectorAll<HTMLElement>("[role='menuitem']") ?? [])];
    const index = items.indexOf(document.activeElement as HTMLElement);
    if (event.key === "Escape") {
      event.preventDefault();
      setOpen(false);
      trigger.current?.focus();
    } else if ((event.key === "ArrowDown" || event.key === "ArrowUp") && items.length) {
      event.preventDefault();
      items[(index + (event.key === "ArrowDown" ? 1 : -1) + items.length) % items.length]?.focus();
    }
  };
  return (
    <div className="broadcast-prompts" ref={root}>
      <button
        ref={trigger}
        type="button"
        className="tile-btn"
        title="Saved prompts"
        aria-label="Saved prompts"
        aria-haspopup="menu"
        aria-expanded={open}
        onClick={() => setOpen((value) => !value)}
      >
        <MessageSquareText size={14} aria-hidden="true" />
      </button>
      {open ? (
        <div className="menu broadcast-prompts-menu" role="menu" aria-label="Saved prompts" onKeyDown={onMenuKey}>
          {PROMPTS.map((prompt) => (
            <button
              key={prompt.id}
              type="button"
              role="menuitem"
              className="menu-item broadcast-prompt"
              title={prompt.text}
              onClick={() => {
                setOpen(false);
                onPick(prompt.text);
              }}
            >
              <span className="broadcast-prompt-name">{prompt.name}</span>
              <span className="broadcast-prompt-text">{prompt.text}</span>
            </button>
          ))}
        </div>
      ) : null}
    </div>
  );
}

export function PromptsShot() {
  const [text, setText] = useState("");
  const [status, setStatus] = useState<string | null>(null);
  const [barHeight, setBarHeight] = useState(82);
  const bar = useRef<HTMLDivElement>(null);
  const input = useRef<HTMLTextAreaElement>(null);
  const footId = useId();
  const tiles = SELECTED;
  const missingAgents = ORDER.length - SELECTED.length;

  // The grid leaves the composer's measured height (--broadcast-h) free.
  useLayoutEffect(() => {
    const element = bar.current;
    if (!element) return;
    const measure = () => setBarHeight(element.offsetHeight);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, []);

  // Grow with the text, one line at a time, up to MAX_INPUT_LINES, as the app does.
  useLayoutEffect(() => {
    const element = input.current;
    if (!element) return;
    element.style.height = "auto";
    const style = getComputedStyle(element);
    const line = parseFloat(style.lineHeight) || 18;
    const chrome = parseFloat(style.paddingTop) + parseFloat(style.paddingBottom) + parseFloat(style.borderTopWidth) + parseFloat(style.borderBottomWidth);
    const content = text ? element.scrollHeight : 0;
    element.style.height = content ? `${Math.min(content, line * MAX_INPUT_LINES + chrome)}px` : `${line + chrome}px`;
  }, [text]);

  const edit = (value: string) => {
    setText(value);
    setStatus(null);
  };
  const send = () => {
    if (!text.trim()) return;
    setStatus(`Sent to ${tiles.length} sessions.`);
    setText("");
  };

  return (
    <Shot id="broadcast" width={FRAME.width} height={FRAME.height}>
      <AppWindow box={BOX}>
        <ActiveCanvas
          style={{ gridTemplateColumns: "1fr", gridTemplateRows: `${TOP_ROW}px ${TOP_ROW}px 1fr 1fr`, paddingBottom: SPACE + barHeight + LIFT }}
          tiles={ORDER.map((id, i) => (
            <Tile key={id} title={id} agent="claude" kbd={`⌘${i + 1}`} device={THIS_MAC}
              selected={SELECTED.includes(id)}
              strip={{ session: id, branch: "main", path: SESSIONS[id].path, started: SESSIONS[id].started }}
            >
              <Term>
                <AnsiScreen id={WIDE[id]} />
              </Term>
            </Tile>
          ))}
        />
        <Viewport width={BOX.width} height={BOX.height} z={8} passThrough>
          {/* Fixed over the canvas's box: the full width of the window, down to
              its bottom edge. In the app the dock sits inside .canvas, which
              sets the lift its padding uses; this layer is outside it. */}
          <div className="broadcast-dock" style={DOCK}>
            <div className="broadcast-fade" aria-hidden="true">
              <span />
              <span />
              <span />
              <span />
            </div>
            <div ref={bar} className="broadcast-bar" role="region" aria-label="Broadcast to selected sessions">
              <div className="broadcast-head">
                <span className="broadcast-title">
                  <Radio size={14} className="broadcast-icon" aria-hidden="true" />
                  Broadcast
                </span>
                <ul className="broadcast-targets" aria-label="Selected sessions">
                  {tiles.map((id) => (
                    <li key={id} className="broadcast-chip" title={id}>
                      <AgentMark agent="claude" size={12} />
                      <span className="broadcast-chip-name">{id}</span>
                      <button type="button" className="broadcast-chip-remove" aria-label={`Remove ${id}`} title="Remove from the broadcast">
                        <X size={11} />
                      </button>
                    </li>
                  ))}
                </ul>
                <button type="button" className="tile-btn broadcast-agents" title="Add every tile running a coding agent in this workspace">
                  <Bot size={14} aria-hidden="true" />
                  All agents<span className="broadcast-agents-count">+{missingAgents}</span>
                </button>
                <button type="button" className="tile-btn broadcast-close" title="Clear selection (Esc)" aria-label="Clear selection">
                  <X size={14} />
                </button>
              </div>
              <div className="broadcast-compose">
                <PromptPicker
                  onPick={(prompt) => {
                    edit(prompt);
                    input.current?.focus();
                  }}
                />
                <div className="broadcast-field">
                  <textarea
                    ref={input}
                    className="broadcast-input"
                    value={text}
                    rows={1}
                    placeholder={`Type a message to send to all ${tiles.length} sessions…`}
                    aria-label={`Send to ${tiles.length} sessions`}
                    aria-describedby={footId}
                    spellCheck={false}
                    maxLength={4096}
                    onChange={(event) => edit(event.target.value)}
                    onKeyDown={(event) => {
                      if (event.key === "Enter" && !event.shiftKey && !event.nativeEvent.isComposing) {
                        event.preventDefault();
                        send();
                      }
                    }}
                  />
                </div>
                <button type="button" className="tile-btn" title="Start dictation" aria-label="Start dictation">
                  <Mic size={13} />
                </button>
                <button
                  type="button"
                  className="tile-btn broadcast-send"
                  aria-label="Send"
                  title="Send (Enter). Shift+Enter adds a line. Sessions waiting on an approval prompt are skipped."
                  disabled={!text.trim()}
                  onClick={send}
                >
                  <SendHorizontal size={15} aria-hidden="true" />
                </button>
              </div>
              <div id={footId} className={`broadcast-foot ${status ? "broadcast-status" : ""}`} role="status">
                {status}
              </div>
            </div>
          </div>
        </Viewport>
      </AppWindow>
    </Shot>
  );
}
